mapper.select:
SELECT t.id, t.task_code AS taskCode, t.out_driver_name AS outDriverName, t.out_driver_phone AS outDriverPhone, t.appointment_start AS appointmentStart, t.appointment_end AS appointmentEnd, t.actual_checkin_time AS checkinTime, CASE WHEN t.actual_checkin_time IS NOT NULL AND t.actual_checkin_time <= t.appointment_end THEN '1' ELSE '0' END AS isOnTime, t.task_status AS taskStatus, (SELECT GROUP_CONCAT(d.dock_name SEPARATOR ',') FROM f_appointment_task_dock d WHERE d.task_id = t.id) AS dockNames FROM f_appointment_task t WHERE t.deleted = 0
AND DATE(t.appointment_start) = #{appointmentDate}
AND t.out_driver_name = #{driverName}
AND t.actual_checkin_time IS NOT NULL AND t.actual_checkin_time <= t.appointment_end
AND (t.actual_checkin_time IS NULL OR t.actual_checkin_time > t.appointment_end)
ORDER BY t.appointment_start DESC
